: "https://en.wikipedia.org/w/index.php?title=Roman_circus_of_M%C3%A9rida&oldid=1360494351", "title": "Roman circus of Mérida", "changes": "sentences selected and shortened", "licence_url": "https://creativecommons.org/licenses/by-sa/4.0/"}, "desc_sha256": "2795bd93d63617071c5faccbcd0821f067fbe19d31fc7ffcb3728fc60a9f1e19"}}', 'teaser-prov-s024-rollback:a9acce8d-1324-434d-913d-519e7c4eb619:raw_data', 'rollback of teaser-prov-s024: raw_data ''{"description_citations": [{"n": 1, "url": "https://en.wikipedia.org/w/index.php?title=Roman_circus_of_M%C3%A9rida&oldid=1360494351", "title": "Wikipedia: Roman circus of Mérida", "domain": "en.wikipedia.org", "license": "CC BY-SA 4.0"}], "_description_provenance": {"v": 1, "ai": "selected", "run": "v3-2026-09-26", "card": null, "lane": "W", "licence": "CC BY-SA 4.0", "sources": [{"id": "W", "url": "https://en.wikipedia.org/w/index.php?title=Roman_circus_of_M%C3%A9rida&oldid=1360494351", "revid": 1360494351, "licence": "CC BY-SA 4.0", "text_sha256": "c784842d0f43b32aebac09d6fc871d5f95c64337f7573114ffbc7ca27aeb8c15", "rev_timestamp": "2026-06-21T20:36:35Z"}], "ai_system": "Claude Opus (Anthropic): anthropic/claude-opus-5-5 (Claude Code agent), an-sites-remediation-2026-09", "sentences": [{"n": 1, "end": 157, "src": "W", "drop": [], "start": 0}, {"n": 1, "end": 298, "src": "W", "drop": [], "start": 158}, {"n": 1, "end": 409, "src": "W", "drop": [[324, 335], [354, 362]], "start": 299}, {"n": 1, "end": 496, "src": "W", "drop": [], "start": 410}, {"n": 1, "end": 1279, "src": "W", "drop": [], "start": 1028}, {"n": 1, "end": 1762, "src": "W", "drop": [], "start": 1537}], "attribution": {"url": "https://en.wikipedia.org/w/index.php?title=Roman_circus_of_M%C3%A9rida&oldid=1360494351", "title": "Roman circus of Mérida", "changes": "sentences selected and shortened", "licence_url": "https://creativecommons.org/licenses/by-sa/4.0/"}, "desc_sha256": "2795bd93d63617071c5faccbcd0821f067fbe19d31fc7ffcb3728fc60a9f1e19"}}'' restored on Roman Circus of Mérida', '2795bd93d63617071c5faccbcd0821f067fbe19d31fc7ffcb3728fc60a9f1e19', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Chariots raced in the Roman Circus of Mérida, more than 400 m long, with room for up to 30,000 spectators. Its triumph gate, the Porta Triumphalis, survives, as does its spina wall."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "chariots raced in the Roman Circus of Mérida [S2]; it is more than 400 m long [S3]; it could hold up to 30,000 spectators [S3]; its triumph gate, the Porta Triumphalis, survives [S6]; its spina wall survives [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Roman Circus of Mérida is a Roman circus used for chariot racing (in Mérida, Spain). [SUPPORTED: https://en.wikipedia.org/wiki/Roman_circus_of_M%C3%A9rida]; It is more than 400 m long. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_circus_of_M%C3%A9rida]; It had room for up to 30,000 spectators. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_circus_of_M%C3%A9rida]; Its triumph gate, the Porta Triumphalis, survives. [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Roman_circus_of_M%C3%A9rida]; Its spina wall survives. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_circus_of_M%C3%A9rida]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 95;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_prov_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'raw_data' THEN p.new_value::jsonb IS NOT DISTINCT FROM p.old_value::jsonb OR p.old_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.old_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_prov_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_prov_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/card-provenance', 'wb-teaser-prov-s024-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card provenance: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.new_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-prov-s024-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-prov-s024-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('raw_data'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: this run stamp journalled % row(s) outside unified_sites.(raw_data)', bad;
    END IF;

    RAISE NOTICE 'teaser card provenance: % of % planned cell(s) changed and journalled over 95 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-prov-s024-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/card-provenance'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-prov-s024-rollback' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('raw_data')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'raw_data' THEN u.raw_data IS NOT DISTINCT FROM l.new_value::jsonb
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
